 async function eventDirectory(eventKind){
  const localSource=environment(),peer=peerEnvironment(),local=await request('directory',{eventKind},localSource);
  if(eventKind!=='private')return local;
  const other=await request('directory',{eventKind},peer);
  if(!local.ok&&!other.ok)return local;
  const combined=[...(local.ok?(local.events||[]).map(event=>({...event,source:localSource})):[]),...(other.ok?(other.events||[]).map(event=>({...event,source:peer})):[])];
  return{ok:true,partial:!local.ok||!other.ok,events:[...new Map(combined.map(event=>[(event.source||localSource)+':'+event.id,event])).values()]};
 }
